// lib/payments.ts
import "server-only"

export async function getBalance(userId: string) {
  const res = await fetch(`${process.env.PAYMENTS_URL}/balance/${userId}`, {
    headers: { Authorization: `Bearer ${process.env.PAYMENTS_KEY}` },
    signal: AbortSignal.timeout(5000),
  })
  if (!res.ok) throw new Error(`Payments API: ${res.status}`)
  const data: { amount: number; currency: string; internalId: string } = await res.json()
  return { amount: data.amount, currency: data.currency } // internalId tashqariga chiqmaydi
}

