// fayl: lib/fetchRetry.ts
export async function fetchRetry(url: string, tries = 3): Promise<Response> {
  for (let i = 1; ; i++) {
    // har urinishga yangi signal — aks holda Next bir xil GET'ni memoizatsiya qilib, eski javobni qaytaradi
    const res = await fetch(url, { signal: AbortSignal.timeout(5000) })
    if (res.ok || i >= tries || res.status < 500) return res
    await new Promise((r) => setTimeout(r, 50 * i))
  }
}

