import Link from "next/link"

export default async function Home({ searchParams }: { searchParams: Promise<{ page?: string }> }) {
  const page = Number((await searchParams).page ?? 1)
  const res = await fetch(`${process.env.API_URL}/recipes?page=${page}&limit=3`)
  const total = Number(res.headers.get("x-total-count"))
  const items: { title: string }[] = await res.json()
  const pages = Math.ceil(total / 3)
  return (
    <main>
      <p>{items.map((i) => i.title).join(", ")}</p>
      <p>{page}/{pages} (jami {total})</p>
      {page < pages && <Link href={`?page=${page + 1}`}>Keyingi</Link>}
    </main>
  )
}

