export type ActionResult<T = void> =
  | { ok: true; data: T }
  | { ok: false; error: string; fieldErrors?: Record<string, string[]> }

export const ok = <T>(data: T): ActionResult<T> => ({ ok: true, data })
export const fail = (error: string, fieldErrors?: Record<string, string[]>): ActionResult<never> =>
  ({ ok: false, error, fieldErrors })

// fayl: app/tables/actions.ts
"use server"
import { ok, fail, type ActionResult } from "@/lib/action-result"

const booked = new Set([3, 7])

export async function bookTable(table: number): Promise<ActionResult<{ table: number }>> {
  if (!Number.isInteger(table) || table < 1 || table > 12) return fail("Bunday stol yo'q")
  if (booked.has(table)) return fail(`${table}-stol band`)
  booked.add(table)
  return ok({ table })
}

