// fayl: app/recipes/new/actions.ts
"use server"
import { z } from "zod"
import { updateTag } from "next/cache"
import { redirect } from "next/navigation"
import { verifySession } from "@/lib/dal"
import { db } from "@/lib/db"

const RecipeSchema = z.object({
  title: z.string().trim().min(3, "Kamida 3 belgi").max(80),
  minutes: z.coerce.number().int().min(1, "Vaqtni kiriting").max(600),
  tags: z.array(z.enum(["milliy", "shirinlik", "vegetarian"])).max(3),
})

export type RecipeFormState = {
  error?: string
  fieldErrors?: { title?: string[]; minutes?: string[]; tags?: string[] }
}

export async function createRecipe(_prev: RecipeFormState, formData: FormData): Promise<RecipeFormState> {
  const session = await verifySession()
  if (!session) redirect("/login?next=/recipes/new")

  const parsed = RecipeSchema.safeParse({
    title: formData.get("title"),
    minutes: formData.get("minutes"),
    tags: formData.getAll("tags"),
  })
  if (!parsed.success) return { fieldErrors: z.flattenError(parsed.error).fieldErrors }

  let id: string
  try {
    id = await db.recipe.create({ ...parsed.data, authorId: session.userId })
  } catch (e) {
    console.error("createRecipe:", e)
    return { error: "Saqlab bo'lmadi, birozdan keyin qayta urinib ko'ring" }
  }

  updateTag("recipes")
  updateTag(`author-${session.userId}`)
  redirect(`/recipes/${id}`)
}

