"use client"
import { useOptimistic } from "react"
import { addComment } from "./actions"

type Comment = { id: string; text: string; sending?: boolean }

export function Comments({ comments }: { comments: Comment[] }) {
  const [optimistic, addOptimistic] = useOptimistic(comments, (current: Comment[], text: string) => [
    ...current,
    { id: `tmp-${current.length}`, text, sending: true },
  ])

  async function action(formData: FormData) {
    const text = String(formData.get("text"))
    addOptimistic(text)     // darhol ro'yxatda
    await addComment(text)  // server: yozish + updateTag("comments")
  }

  return (
    <>
      <ul>{optimistic.map((c) => <li key={c.id}>{c.text}{c.sending && " (yuborilmoqda...)"}</li>)}</ul>
      <form action={action}><input name="text" required /><button>Yuborish</button></form>
    </>
  )
}

