"use server"

export type PromoState = { attempts: number; message: string; discount: number }

export async function applyPromo(prev: PromoState, formData: FormData): Promise<PromoState> {
  if (prev.attempts >= 3) return { ...prev, message: "Urinishlar tugadi" }
  const code = String(formData.get("code") ?? "").trim().toUpperCase()
  const attempts = prev.attempts + 1
  if (code === "OSH20") return { attempts, message: "20% chegirma qo'llandi", discount: 20 }
  return { attempts, message: `Kod noto'g'ri (${attempts}/3)`, discount: 0 }
}

