"use client"
import { startTransition, useActionState, useState } from "react"
import { postReview, type ReviewState } from "./actions"

export function ReviewForm() {
  const [text, setText] = useState("")
  const [state, formAction, isPending] = useActionState(async (prev: ReviewState, formData: FormData) => {
