"use client"
import { startTransition, useOptimistic, useState } from "react"
import { rateRecipe } from "./actions"

export function Rating({ slug, rating }: { slug: string; rating: number }) {
  const [shown, setShown] = useOptimistic(rating)
  const [error, setError] = useState("")

  function rate(value: number) {
    setError("")
    startTransition(async () => {
      setShown(value)
      const res = await rateRecipe(slug, value)
      if (!res.ok) setError(res.error)
    })
  }

  return (
    <div>
      {[1, 2, 3, 4, 5].map((n) => (
        <button key={n} onClick={() => rate(n)} aria-label={`${n} yulduz`}>
          {n <= shown ? "★" : "☆"}
        </button>
      ))}
      {error && <p role="alert">{error}</p>}
    </div>
  )
}

