// fayl: app/recipes/[id]/photo/actions.ts
"use server"
import { putObject } from "@/lib/storage" // S3 / Blob — public/ ga yozmang

const TYPES = ["image/jpeg", "image/png", "image/webp"]

export type PhotoState = { error?: string; url?: string }

export async function uploadPhoto(recipeId: string, prev: PhotoState, formData: FormData): Promise<PhotoState> {
  const file = formData.get("photo")
  if (!(file instanceof File) || file.size === 0) return { error: "Rasm tanlang" }
  if (!TYPES.includes(file.type)) return { error: "Faqat JPG, PNG yoki WebP" }
  if (file.size > 2 * 1024 * 1024) return { error: "Rasm 2 MB dan oshmasin" }
  const url = await putObject(`recipes/${recipeId}.${file.type.split("/")[1]}`, file)
  return { url }
}

