// fayl: app/catering/wizard/actions.ts
"use server"
import { z } from "zod"

const Step1 = z.object({
  name: z.string().trim().min(2, "Ism kiriting"),
  phone: z.string().regex(/^\+998\d{9}$/, "Telefon noto'g'ri"),
})
const Step2 = z.object({
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "Sanani tanlang"),
  guests: z.coerce.number().int().min(10, "Kamida 10 mehmon"),
})

export type Wizard = { step: 1 | 2 | 3 | 4; data: Record<string, string>; error?: string }

export async function wizard(prev: Wizard, formData: FormData): Promise<Wizard> {
  const fields = Object.fromEntries([...formData].filter(([k]) => !k.startsWith("$ACTION")))
  const data = { ...prev.data, ...(fields as Record<string, string>) }
  const schema = prev.step === 1 ? Step1 : prev.step === 2 ? Step2 : Step1.extend(Step2.shape)
  const parsed = schema.safeParse(data)
  if (!parsed.success) return { ...prev, data, error: parsed.error.issues[0].message }
  if (prev.step === 1) return { step: 2, data }
  if (prev.step === 2) return { step: 3, data }
  // await db.cateringOrder.create({ data: parsed.data })
  return { step: 4, data }
}

