// fayl: app/catering/wizard/step-actions.ts
"use server"

export type Steps = { step: number; data: Record<string, string> }

export async function stepAction(prev: Steps, formData: FormData): Promise<Steps> {
  const intent = formData.get("intent")
  const fields = Object.fromEntries([...formData].filter(([k]) => k !== "intent" && !k.startsWith("$ACTION")))
  const data = { ...prev.data, ...(fields as Record<string, string>) } // orqaga ketganda ham saqlaymiz
  if (intent === "back") return { step: Math.max(1, prev.step - 1), data }
  // ... joriy qadam schema'si bilan tekshirish (oldingi misoldagidek)
  return { step: Math.min(3, prev.step + 1), data }
}

