  minutes: z.coerce.number("Son kiriting").int().min(1, "Kamida 1 daqiqa"),
  steps: z.string().trim().min(20, "Tayyorlash tartibini batafsilroq yozing"),
})
type Key = keyof z.infer<typeof RecipeSchema>
