// fayl: app/recipes/new/actions.ts
"use server"
import { updateTag } from "next/cache"
import { redirect } from "next/navigation"
import { z } from "zod"
import { verifySession } from "@/lib/dal"
import { db } from "@/lib/db"
import { RecipeSchema, type RecipeState } from "@/lib/schemas/recipe"

export async function createRecipe(prev: RecipeState, formData: FormData): Promise<RecipeState> {
  const session = await verifySession() // kirmagan bo'lsa → redirect("/login")
  const values = {
    title: String(formData.get("title") ?? ""),
    minutes: String(formData.get("minutes") ?? ""),
    steps: String(formData.get("steps") ?? ""),
  }
  const parsed = RecipeSchema.safeParse(values)
  if (!parsed.success) return { errors: z.flattenError(parsed.error).fieldErrors, values }

  let id: string
  try {
    id = (await db.recipe.create({ data: { ...parsed.data, authorId: session.userId } })).id
  } catch {
    return { message: "Saqlab bo'lmadi, birozdan keyin qayta urinib ko'ring", values }
  }
  updateTag("recipes")
  redirect(`/recipes/${id}`)
}

