"use client"
import { startTransition, useActionState, useOptimistic, useState } from "react"
import { renameList, type RenameResult } from "./actions"

export function TitleEditor({ id, title }: { id: string; title: string }) {
  const [editing, setEditing] = useState(false)
  const [shown, setShown] = useOptimistic(title)
  const [state, formAction, isPending] = useActionState(async (_prev: RenameResult, formData: FormData) => {
    setShown(String(formData.get("title") ?? "").trim()) // darhol yangi nom
    const res = await renameList(id, formData)
    if (!res.error) startTransition(() => setEditing(false)) // await'dan keyin — startTransition
    return res
  }, {})

  if (!editing || isPending) {
    return (
      <h2>
        <button onClick={() => setEditing(true)} disabled={isPending}>
          {shown}
          {isPending ? " ⏳" : " ✎"}
        </button>
      </h2>
    )
  }
  return (
    <form action={formAction}>
      <input name="title" defaultValue={state.value ?? title} autoFocus aria-label="Ro'yxat nomi" />
      <button>Saqlash</button>
      <button type="button" onClick={() => setEditing(false)}>Bekor</button>
      {state.error && <p role="alert">{state.error}</p>}
    </form>
  )
}

