import { Suspense } from "react"
import { prisma } from "@/lib/prisma"

type SP = PageProps<"/search">["searchParams"]

async function Results({ searchParams }: { searchParams: SP }) {
  const { q } = await searchParams
  const term = (typeof q === "string" ? q : "").trim().slice(0, 50)
  if (!term) return <p>Qidiruv so'zini kiriting</p>

  const found = await prisma.recipe.findMany({
    where: { published: true, title: { contains: term, mode: "insensitive" } },
    select: { id: true, title: true },
    take: 20,
  })

  if (found.length === 0) return <p>"{term}" bo'yicha hech narsa topilmadi</p>
  return (
    <ul>
      {found.map((r) => (
        <li key={r.id}>{r.title}</li>
      ))}
    </ul>
  )
}

export default function SearchPage({ searchParams }: PageProps<"/search">) {
  return (
    <Suspense fallback={<p>Qidirilmoqda...</p>}>
      <Results searchParams={searchParams} />
    </Suspense>
  )
}

