"use server"
import { Prisma } from "@/app/generated/prisma/client"
import { prisma } from "@/lib/prisma"
import { verifySession } from "@/lib/dal/session"

export type State = { error?: string; ok?: boolean }

export async function createRecipe(_prev: State, formData: FormData): Promise<State> {
  const { userId } = await verifySession()
  const title = String(formData.get("title") ?? "").trim()
  const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, "-")

  try {
    await prisma.recipe.create({ data: { title, slug, minutes: 30, authorId: userId } })
    return { ok: true }
  } catch (e) {
    // P2002 — unique cheklov buzildi (slug band)
    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
      return { error: `"${title}" nomli retsept allaqachon bor` }
    }
    throw e // kutilmagan xato — error.tsx
  }
}

