// fayl: lib/dal/orders.ts
import "server-only"
import { prisma } from "@/lib/prisma"

export async function placeOrder(userId: number, productId: number, qty: number) {
  return prisma.$transaction(async (tx) => {
    // 1) Qoldiqni kamaytiramiz
    const product = await tx.product.update({
      where: { id: productId },
      data: { stock: { decrement: qty } },
      select: { name: true, stock: true },
    })

    // 2) Yetmasa — xato: 1-qadam ham bekor bo'ladi (ROLLBACK)
    if (product.stock < 0) {
      throw new Error(`${product.name}: omborda yetarli emas`)
    }

    // 3) Buyurtmani yozamiz
    return tx.order.create({
      data: { userId, productId, qty },
      select: { id: true },
    })
  })
}

