// fayl: db/schema.ts
import { boolean, integer, numeric, pgTable, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core"

export const users = pgTable("users", {
  id: integer().primaryKey().generatedAlwaysAsIdentity(),
  email: text().notNull().unique(),
  name: text().notNull(),
  passwordHash: text("password_hash").notNull(),
})

export const recipes = pgTable(
  "recipes",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    title: text().notNull(),
    slug: text().notNull(),
    price: numeric({ precision: 10, scale: 2 }), // JS'da string
    published: boolean().default(false).notNull(),
    authorId: integer("author_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [uniqueIndex("recipes_slug_idx").on(t.slug)],
)

// Tiplar sxemadan o'zi chiqadi
export type Recipe = typeof recipes.$inferSelect
export type NewRecipe = typeof recipes.$inferInsert

