"use server"
import { updateTag } from "next/cache"
import { redirect } from "next/navigation"
import { z } from "zod"
import { db } from "@/db"
import { recipes } from "@/db/schema"
import { verifySession } from "@/lib/dal/session"

const Input = z.object({
  title: z.string().trim().min(2, "Nom kamida 2 harf").max(80),
  price: z.coerce.number().positive("Narx musbat bo'lsin"),
})

export async function createRecipe(_prev: { error?: string }, formData: FormData) {
  const { userId } = await verifySession()
  const parsed = Input.safeParse(Object.fromEntries(formData))
  if (!parsed.success) return { error: parsed.error.issues[0].message }

  const { title, price } = parsed.data
  const [row] = await db
    .insert(recipes)
    .values({
      title,
      slug: title.toLowerCase().replace(/[^a-z0-9]+/g, "-"),
      price: price.toFixed(2),
      authorId: userId,
    })
    .returning({ id: recipes.id, slug: recipes.slug })

  updateTag("recipes")
  redirect(`/recipes/${row.slug}`)
}

