"use server"
import { and, eq } from "drizzle-orm"
import { updateTag } from "next/cache"
import { db } from "@/db"
import { recipes } from "@/db/schema"
import { verifySession } from "@/lib/dal/session"

export async function renameRecipe(id: number, title: string) {
  const { userId } = await verifySession()
  const updated = await db
    .update(recipes)
    .set({ title })
    .where(and(eq(recipes.id, id), eq(recipes.authorId, userId))) // faqat o'zinikini
    .returning({ id: recipes.id })

  if (updated.length === 0) return { error: "Topilmadi yoki ruxsat yo'q" }
  updateTag(`recipe-${id}`)
  return { ok: true }
}

export async function deleteRecipe(id: number) {
  const { userId } = await verifySession()
  const deleted = await db
    .delete(recipes)
    .where(and(eq(recipes.id, id), eq(recipes.authorId, userId)))
    .returning({ id: recipes.id })

  if (deleted.length === 0) return { error: "Topilmadi yoki ruxsat yo'q" }
  updateTag("recipes")
  return { ok: true }
}

