// fayl: app/api/webhooks/db/route.ts
import { revalidateTag } from "next/cache"
import type { NextRequest } from "next/server"

export async function POST(req: NextRequest) {
  if (req.headers.get("x-webhook-secret") !== process.env.DB_WEBHOOK_SECRET) {
    return Response.json({ error: "ruxsat yo'q" }, { status: 401 })
  }

  const { table, id } = (await req.json()) as { table: string; id: number }
  if (table !== "recipes") return Response.json({ revalidated: false })

  revalidateTag("recipes", "max") // ro'yxatlar
  revalidateTag(`recipe-${id}`, "max") // bitta retsept sahifasi
  return Response.json({ revalidated: true, tags: ["recipes", `recipe-${id}`] })
}

