import { connection } from "next/server"
import { prisma } from "@/lib/prisma"

function withTimeout<T>(p: Promise<T>, ms: number) {
  return Promise.race([
    p,
    new Promise<never>((_, reject) => setTimeout(() => reject(new Error("timeout")), ms)),
  ])
}

export async function GET() {
  await connection() // har so'rovda tekshiriladi
  try {
    await withTimeout(prisma.$queryRaw`SELECT 1`, 2000)
    return Response.json({ db: "ok" }, { headers: { "Cache-Control": "no-store" } })
  } catch (e) {
    console.error("DB health:", (e as Error).message)
    return Response.json({ db: "down" }, { status: 503 })
  }
}

