"use client"
import { use, useState } from "react"
import type { Comment } from "@/lib/comments"

type Page = { items: Comment[]; hasMore: boolean }

export function Comments({ first }: { first: Promise<Page> }) {
  const initial = use(first) // serverdan kelgan 1-sahifa
  const [items, setItems] = useState(initial.items)
  const [page, setPage] = useState(1)
  const [hasMore, setHasMore] = useState(initial.hasMore)

  async function loadMore() {
    const res = await fetch(`/api/comments?page=${page + 1}`)
    const next: Page = await res.json()
    setItems((prev) => [...prev, ...next.items])
    setHasMore(next.hasMore)
    setPage(page + 1)
  }

  return (
    <div>
      <ul>{items.map((c) => <li key={c.id}>{c.text}</li>)}</ul>
      {hasMore && <button onClick={loadMore}>Yana yuklash</button>}
    </div>
  )
}

