  const params = new URLSearchParams({ status: filter.status, page: String(filter.page) })
  const res = await fetch(`${url}?${params}`)
  if (!res.ok) throw new Error("Buyurtmalar olinmadi")
  return res.json() as Promise<{ ids: number[] }>
}

export function OrdersPage() {
  const [filter, setFilter] = useState<Filter>({ status: "new", page: 1 })
  const { data } = useSWR(["/api/orders", filter], fetchOrders)

  return (
    <div>
      <button onClick={() => setFilter({ ...filter, status: "done" })}>Bajarilganlar</button>
      <p>
        {filter.status}, {filter.page}-sahifa: {data?.ids.join(", ") ?? "..."}
      </p>
    </div>
  )
}

