"use client"
import { useState } from "react"
import useSWR from "swr"
import { fetcher } from "@/lib/fetcher"

type Likes = { likes: number }

async function sendLike(url: string): Promise<Likes> {
  const res = await fetch(url, { method: "POST" })
  if (!res.ok) throw new Error("Like saqlanmadi")
  return res.json()
}

export function LikeButton({ id }: { id: string }) {
  const key = `/api/recipes/${id}/like`
  const { data, mutate } = useSWR<Likes>(key, fetcher)
  const [message, setMessage] = useState("")

  async function like() {
    if (!data) return
    setMessage("")
    try {
      await mutate(sendLike(key), {
        optimisticData: { likes: data.likes + 1 }, // darhol ko'rsatiladi
        rollbackOnError: true, // xato bo'lsa eski qiymat qaytadi
        populateCache: true, // server javobi keshga yoziladi
        revalidate: false, // javob to'liq — qayta GET shart emas
      })
    } catch (e) {
      setMessage((e as Error).message)
    }
  }

  return (
    <div>
      <button onClick={like}>♥ {data?.likes ?? "..."}</button>
      {message && <small> {message}</small>}
    </div>
  )
}

