// fayl: app/feed.tsx
"use client"
import { useEffect, useRef } from "react"
import useSWRInfinite from "swr/infinite"
import { fetcher } from "@/lib/fetcher"

type Page = { items: { id: number; title: string }[]; next: number | null }

function getKey(_index: number, prev: Page | null) {
  if (prev && prev.next === null) return null // oxiri — boshqa so'rov yo'q
  return `/api/feed?cursor=${prev ? prev.next : 0}`
}

export function Feed() {
  const { data, size, setSize, isValidating } = useSWRInfinite<Page>(getKey, fetcher, {
    revalidateFirstPage: false, // har yangi sahifada 1-sahifani qayta so'ramaslik
  })
  const sentinel = useRef<HTMLDivElement>(null)
  const done = data?.at(-1)?.next === null

  useEffect(() => {
    const el = sentinel.current
    if (!el || done) return
    const io = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting && !isValidating) setSize(size + 1)
    })
    io.observe(el)
    return () => io.disconnect()
  }, [size, setSize, isValidating, done])

  return (
    <div>
      {data?.flatMap((p) => p.items).map((post) => <p key={post.id}>{post.title}</p>)}
      <div ref={sentinel}>{done ? "Hammasi shu" : "Yuklanmoqda..."}</div>
    </div>
  )
}

