  const { data, isPending, isError, isPlaceholderData } = useQuery({
    queryKey: ["dishes", page],
    queryFn: () => getPage(page),
    placeholderData: keepPreviousData, // yangi sahifagacha eskisi turadi
  })

  if (isPending) return <p>Yuklanmoqda...</p>
  if (isError) return <p>Sahifani yuklab bo'lmadi</p>
  return (
    <div style={{ opacity: isPlaceholderData ? 0.5 : 1 }}>
      <p>{data.items.join(", ")}</p>
      <button onClick={() => setPage((p) => p - 1)} disabled={page === 1}>
        Oldingi
      </button>
      <button onClick={() => setPage((p) => p + 1)} disabled={isPlaceholderData || !data.hasMore}>
        Keyingi
      </button>
    </div>
  )
}

