import { useMutation, useQueryClient } from "@tanstack/react-query"

type Todo = { id: number; title: string; done: boolean }

async function toggleTodo(todo: Todo): Promise<Todo> {
  const res = await fetch(`/api/todos/${todo.id}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ done: !todo.done }),
  })
  if (!res.ok) throw new Error("Saqlanmadi")
  return res.json()
}

export function useToggleTodo() {
  const queryClient = useQueryClient()
  const queryKey = ["todos"]

  return useMutation({
    mutationFn: toggleTodo,
    onMutate: async (todo) => {
      await queryClient.cancelQueries({ queryKey })
      const previous = queryClient.getQueryData<Todo[]>(queryKey)
      queryClient.setQueryData<Todo[]>(queryKey, (old = []) =>
        old.map((t) => (t.id === todo.id ? { ...t, done: !t.done } : t)),
      )
      return { previous } // onError'ga uchinchi argument bo'lib boradi
    },
    onError: (_error, _todo, context) => {
      queryClient.setQueryData(queryKey, context?.previous) // orqaga qaytarish
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey }),
  })
}

