"use client"
import { useInfiniteQuery } from "@tanstack/react-query"

type Page = { items: { id: number; title: string }[]; next: number | null }

async function getFeed(cursor: number): Promise<Page> {
  const res = await fetch(`/api/feed?cursor=${cursor}`)
