export function FeedList() {
  const { data, fetchNextPage, hasNextPage, isFetchingNextPage, status } = useInfiniteQuery({
    queryKey: ["feed"],
    queryFn: ({ pageParam }) => getFeed(pageParam),
    initialPageParam: 0,
    getNextPageParam: (lastPage) => lastPage.next, // null — boshqa sahifa yo'q
  })

  if (status === "pending") return <p>Yuklanmoqda...</p>
  if (status === "error") return <p>Lentani yuklab bo'lmadi</p>

  return (
    <div>
      {data.pages.map((page) => page.items.map((p) => <p key={p.id}>{p.title}</p>))}
      <button onClick={() => fetchNextPage()} disabled={!hasNextPage || isFetchingNextPage}>
        {isFetchingNextPage ? "Yuklanmoqda..." : hasNextPage ? "Yana yuklash" : "Hammasi shu"}
      </button>
    </div>
  )
}

