// fayl: app/user-search.tsx
"use client"
import { useEffect, useState } from "react"
import { useQuery } from "@tanstack/react-query"

function useDebounced<T>(value: T, ms: number) {
  const [debounced, setDebounced] = useState(value)
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), ms)
    return () => clearTimeout(t)
  }, [value, ms])
  return debounced
}

export function UserSearch() {
  const [text, setText] = useState("")
  const q = useDebounced(text.trim(), 300)
  const { data = [], isFetching } = useQuery({
    queryKey: ["users", q],
    queryFn: async ({ signal }): Promise<string[]> => {
      const res = await fetch(`/api/users?q=${encodeURIComponent(q)}`, { signal })
      if (!res.ok) throw new Error("Qidiruv xatosi")
      return res.json()
    },
    enabled: q.length >= 2,
    staleTime: 60_000,
  })

  return (
    <div>
      <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Ism" />
      {isFetching ? <p>Qidirilmoqda...</p> : <p>{data.join(", ")}</p>}
    </div>
  )
}

