// fayl: lib/step.ts
import { cache } from "react"
import { connection } from "next/server"

const requestStart = cache(() => performance.now())   // har HTTP so'rovda bitta boshlang'ich nuqta

export async function step<T>(label: string, ms: number, value: T): Promise<T> {
  await connection()
  const at = () => `+${Math.round(performance.now() - requestStart())} ms`.padEnd(9)
  console.log(`${at()} ${label} boshlandi`)
  await new Promise((resolve) => setTimeout(resolve, ms))   // sekin manba o'rnida
  console.log(`${at()} ${label} tugadi`)
  return value
}

