// fayl: lib/all-or-abort.ts
export async function allOrAbort<T>(tasks: ((signal: AbortSignal) => Promise<T>)[]): Promise<T[]> {
  const controller = new AbortController()
  try {
    return await Promise.all(tasks.map((task) => task(controller.signal)))
  } catch (err) {
    controller.abort(err)          // qolgan so'rovlar AbortError bilan to'xtaydi
    throw err
  }
}

