// fayl: lib/hedged.ts
export async function hedged<T>(primary: string, backup: string, hedgeAfterMs = 150): Promise<T> {
  const controller = new AbortController()
  const get = async (url: string) => {
    const res = await fetch(url, { signal: controller.signal })
    if (!res.ok) throw new Error(`${url}: ${res.status}`)
    return (await res.json()) as T
  }
  const first = get(primary)
  const second = new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => get(backup).then(resolve, reject), hedgeAfterMs)
    first.then(() => clearTimeout(timer), () => {})   // birinchisi ulgursa — zaxiraga so'rov ketmaydi
  })
  try {
    return await Promise.any([first, second])
  } finally {
    controller.abort()                                // kech qolganini to'xtatish
  }
}

