// fayl: app/api/report/route.ts
export async function GET(request: Request) {
  const signal = AbortSignal.any([request.signal, AbortSignal.timeout(3000)])
  try {
    const res = await fetch(`${process.env.REPORTS_URL}/heavy`, { signal })
    return Response.json(await res.json())
  } catch (err) {
    if (signal.reason instanceof DOMException && signal.reason.name === "TimeoutError") {
      return Response.json({ error: "Hisobot 3 soniyada tayyor bo'lmadi" }, { status: 504 })
    }
    if (request.signal.aborted) return new Response(null, { status: 499 })   // mijoz ketdi
    throw err
  }
}

