import { after, connection } from "next/server"
import { kv } from "@/lib/kv"                 // Redis yoki boshqa kalit-qiymat ombori

type Rates = { usd: number }

async function fetchLive(): Promise<Rates> {
  const res = await fetch(`${process.env.RATES_URL}/latest`)
  if (!res.ok) throw new Error(`rates: ${res.status}`)
  return res.json()
}

export async function Rates() {
  await connection()
  const saved = fetchLive().then(async (r) => {
    await kv.set("rates:last", r)             // har muvaffaqiyatli javob saqlanadi
    return r
  })
  const late = new Promise<null>((resolve) => setTimeout(() => resolve(null), 500))
  const fresh = await Promise.race([saved.catch(() => null), late])

  if (fresh) return <p>USD: {fresh.usd} so'm (jonli)</p>

  after(() => saved.catch(() => {}))          // javobdan keyin jonli so'rov tugashini kutadi
  const last = await kv.get<Rates>("rates:last")
  return <p>USD: {last?.usd ?? "—"} so'm (oxirgi ma'lum qiymat)</p>
}

// fayl: lib/breaker.ts
type State = { failures: number; openUntil: number }
const states = new Map<string, State>()

export async function withBreaker<T>(name: string, task: () => Promise<T>, fallback: T): Promise<T> {
  const s = states.get(name) ?? { failures: 0, openUntil: 0 }
  states.set(name, s)
  if (Date.now() < s.openUntil) return fallback          // ochiq: chaqirmaymiz
  try {
    const result = await task()
    s.failures = 0                                       // muvaffaqiyat — hisoblagich nolga
    return result
  } catch (err) {
    s.failures++
    if (s.failures >= 3) {
      s.openUntil = Date.now() + 30_000                  // 30 s dam
      console.warn(`[breaker] ${name} ochildi: ${(err as Error).message}`)
    }
    return fallback
  }
}

