import { recalcInvoice, notifyTelegram } from "@/lib/billing"

export const maxDuration = 30     // soniya; after ham shu chegara ichida tugashi kerak

export async function POST(request: Request) {
  const body = await request.text()
  if (!verifySignature(body, request.headers.get("x-signature"))) {
    return new Response("imzo noto'g'ri", { status: 401 })
  }
  const event = JSON.parse(body) as { invoiceId: string; amount: number }

  after(async () => {
    await recalcInvoice(event.invoiceId)           // ~4 s
    await notifyTelegram(`To'lov: ${event.amount} so'm`)
  })

  return Response.json({ received: true })         // provayder darhol javob oladi
}

// fayl: lib/timing.ts
export function createTimer() {
  const marks: string[] = []
  return {
    async measure<T>(name: string, task: () => Promise<T>): Promise<T> {
      const start = performance.now()
      try {
        return await task()
      } finally {
        marks.push(`${name};dur=${Math.round(performance.now() - start)}`)
      }
    },
    header: () => marks.join(", "),
  }
}

