export async function GET() {
  await connection()
  const t = createTimer()
  const user = await t.measure("user", () => getUser(7))
  const [orders, news] = await Promise.all([
    t.measure("orders", () => getOrders(user.id)),
    t.measure("news", () => getNews()),
  ])
  return Response.json(
    { user: user.name, orders: orders.length, news: news.length },
    { headers: { "Server-Timing": t.header() } },
  )
}

