import { revalidatePath, revalidateTag } from "next/cache"
import type { NextRequest } from "next/server"

type CmsEvent = { model: "post" | "author"; slug: string }

export async function POST(request: NextRequest) {
  if (request.headers.get("x-webhook-secret") !== process.env.CMS_WEBHOOK_SECRET) {
    return Response.json({ error: "Ruxsat yo'q" }, { status: 401 })
  }
  const event = (await request.json()) as CmsEvent

  if (event.model === "post") {
    revalidatePath(`/blog/${event.slug}`)   // maqolaning o'zi
    revalidatePath("/blog")                 // ro'yxat sahifasi
  }
  if (event.model === "author") {
    revalidateTag(`author-${event.slug}`, "max")   // muallif ko'rsatilgan hamma joy
  }
  return Response.json({ revalidated: true, model: event.model, slug: event.slug })
}

