const redis = createClient({ url: process.env.REDIS_URL })
await redis.connect()

const replacer = (_key, value) =>
  value instanceof Map ? { __map: [...value] }
    : value?.type === "Buffer" ? { __buf: Buffer.from(value.data).toString("base64") }
    : value
const reviver = (_key, value) =>
  value?.__map ? new Map(value.__map) : value?.__buf ? Buffer.from(value.__buf, "base64") : value

export default class CacheHandler {
  constructor(options) {
    this.options = options
  }

  async get(key) {
    const raw = await redis.get(`isr:${key}`)
    return raw ? JSON.parse(raw, reviver) : null
  }

  async set(key, data, ctx) {
    const headerTags = String(data?.headers?.["x-next-cache-tags"] ?? "").split(",").filter(Boolean)
    const tags = [...(ctx.tags ?? []), ...headerTags]   // fetch teglari + sahifa teglari
    const entry = { value: data, lastModified: Date.now(), tags }
    await redis.set(`isr:${key}`, JSON.stringify(entry, replacer), { EX: 60 * 60 * 24 * 7 })
    for (const tag of tags) await redis.sAdd(`tag:${tag}`, key)
  }

  async revalidateTag(tags) {
    for (const tag of [tags].flat()) {
      const keys = await redis.sMembers(`tag:${tag}`)
      if (keys.length) await redis.del(keys.map((k) => `isr:${k}`))   // soddalashtirilgan: o'chiradi
    }
  }

  resetRequestCache() {}
}

// fayl: lib/cms.ts
import "server-only"

const CMS = process.env.CMS_URL

export type Post = { slug: string; title: string; body: string }

export async function getPost(slug: string): Promise<Post | null> {
  const res = await fetch(`${CMS}/posts/${slug}`, { next: { tags: ["posts", `post-${slug}`] } })
  if (res.status === 404) return null
  if (!res.ok) throw new Error(`CMS ${res.status}`)
  return res.json()
}

export async function getTopSlugs(limit: number): Promise<string[]> {
  const res = await fetch(`${CMS}/posts?sort=views&limit=${limit}`, { next: { tags: ["posts"] } })
  return ((await res.json()) as Post[]).map((p) => p.slug)
}

// fayl: app/blog/[slug]/page.tsx
import type { Metadata } from "next"
import { notFound } from "next/navigation"
import { getPost, getTopSlugs } from "@/lib/cms"

export const revalidate = 86400   // zaxira: webhook kelmasa ham kuniga bir marta

export async function generateStaticParams() {
  return (await getTopSlugs(30)).map((slug) => ({ slug }))
}

export async function generateMetadata({ params }: PageProps<"/blog/[slug]">): Promise<Metadata> {
  const post = await getPost((await params).slug)   // sahifadagi bilan bitta so'rov
  return { title: post?.title ?? "Topilmadi" }
}

export default async function PostPage({ params }: PageProps<"/blog/[slug]">) {
  const post = await getPost((await params).slug)
  if (!post) notFound()
  return (
    <article>
      <h1>{post.title}</h1>
      <p>{post.body}</p>
    </article>
  )
}

// fayl: app/api/cms-webhook/route.ts
import { revalidateTag } from "next/cache"
import type { NextRequest } from "next/server"

export async function POST(request: NextRequest) {
  if (request.headers.get("x-webhook-secret") !== process.env.CMS_WEBHOOK_SECRET) {
    return Response.json({ error: "Ruxsat yo'q" }, { status: 401 })
  }
  const { slug, event } = (await request.json()) as { slug: string; event: "updated" | "deleted" }
  revalidateTag(`post-${slug}`, event === "deleted" ? { expire: 0 } : "max")
  revalidateTag("posts", "max")   // ro'yxatlar va mashhurlar
  return Response.json({ ok: true, slug, event })
}
